const terms = get(ctx.entry, 'terms', {});
const extension = get(ctx.entry, 'employee_extension_data', {});
const limits = get(ctx.lookup, 'terms', {});
return Object.keys(limits).every((key) => {
	const rule = limits[key];
	const value = get(terms, key, get(extension, key, null));
	if (value == null) return get(rule, 'required', false) !== true;
	const number = Number(value);
	if (get(rule, 'integer', false) === true && number !== Math.trunc(number)) return false;
	const floor = get(rule, 'exclusive_minimum', null);
	if (floor !== null && !(number > floor)) return false;
	const minimum = get(rule, 'minimum', null);
	if (minimum !== null && !(number >= minimum)) return false;
	const maximum = get(rule, 'maximum', null);
	return maximum === null || number <= maximum;
});

const extension = get(ctx.entry, 'entity_extension_data', {});
const limits = get(ctx.lookup, 'entity', {});
return Object.keys(limits).every((key) => {
	const rule = limits[key];
	const value = get(extension, key, null);
	if (value == null) return get(rule, 'required', false) !== true;
	if (typeof value === 'string') return value !== '';
	const number = Number(value);
	if (get(rule, 'integer', false) === true && number !== Math.trunc(number)) return false;
	const floor = get(rule, 'exclusive_minimum', null);
	if (floor !== null && !(number > floor)) return false;
	const maximum = get(rule, 'maximum', null);
	return maximum === null || number <= maximum;
});

